cat > Currencies/Currency.cs <<'EOF'
namespace CashRegister.Domain.Currencies;

/// <summary>A currency and the denominations a cashier can hand back.</summary>
public sealed class Currency
{
    public Currency(string code, string displayName, IEnumerable<Denomination> denominations)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(code);
        ArgumentException.ThrowIfNullOrWhiteSpace(displayName);
        ArgumentNullException.ThrowIfNull(denominations);

        var ordered = denominations.OrderByDescending(d => d.ValueInMinorUnits).ToList();
        if (ordered.Count == 0)
        {
            throw new ArgumentException("A currency needs at least one denomination.", nameof(denominations));
        }

        if (ordered.Select(d => d.ValueInMinorUnits).Distinct().Count() != ordered.Count)
        {
            throw new ArgumentException("Denomination values must be unique.", nameof(denominations));
        }

        // Every amount must be payable exactly, so the smallest unit has to be present.
        if (ordered[^1].ValueInMinorUnits != 1)
        {
            throw new ArgumentException("A currency must include a denomination worth one minor unit.", nameof(denominations));
        }

        Code = code.ToUpperInvariant();
        DisplayName = displayName;
        Denominations = ordered.AsReadOnly();
    }

    public string Code { get; }

    public string DisplayName { get; }

    /// <summary>Denominations ordered from largest to smallest value.</summary>
    public IReadOnlyList<Denomination> Denominations { get; }
}
EOF
