using CashRegister.Domain.Currencies;

namespace CashRegister.Domain.Change;

/// <summary>A single sale: what was owed and what the customer handed over, in minor units.</summary>
public sealed record Transaction
{
    public Transaction(long owed, long paid, Currency currency)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(owed);
        ArgumentOutOfRangeException.ThrowIfNegative(paid);
        ArgumentNullException.ThrowIfNull(currency);
        if (paid < owed)
        {
            throw new ArgumentException($"Amount paid ({paid}) is less than amount owed ({owed}).", nameof(paid));
        }

        Owed = owed;
        Paid = paid;
        Currency = currency;
    }

    public long Owed { get; }

    public long Paid { get; }

    public Currency Currency { get; }

    public long ChangeDue => Paid - Owed;
}
