cat > Change/MinimalChangeStrategy.cs <<'EOF'
using CashRegister.Domain.Currencies;

namespace CashRegister.Domain.Change;

/// <summary>
/// Fewest pieces using the greedy algorithm. Greedy is optimal for canonical coin systems
/// such as USD and EUR; a non-canonical currency would need a different strategy.
/// </summary>
public sealed class MinimalChangeStrategy : IChangeStrategy
{
    public string Key => ChangeStrategyKeys.Minimal;

    public IReadOnlyList<ChangeLine> MakeChange(long amount, Currency currency)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(amount);
        ArgumentNullException.ThrowIfNull(currency);

        var lines = new List<ChangeLine>();
        var remaining = amount;
        foreach (var denomination in currency.Denominations)
        {
            var count = remaining / denomination.ValueInMinorUnits;
            if (count > 0)
            {
                lines.Add(new ChangeLine(denomination, count));
                remaining -= count * denomination.ValueInMinorUnits;
            }
        }

        return lines;
    }
}
EOF
cat > Change/RandomChangeStrategy.cs <<'EOF'
using CashRegister.Domain.Currencies;

namespace CashRegister.Domain.Change;

/// <summary>
/// Picks a random count of each denomination, largest first; the smallest unit makes up
/// whatever is left, so the total is always exact.
/// </summary>
public sealed class RandomChangeStrategy(Random random) : IChangeStrategy
{
    private readonly Random _random = random ?? throw new ArgumentNullException(nameof(random));

    public string Key => ChangeStrategyKeys.Random;

    public IReadOnlyList<ChangeLine> MakeChange(long amount, Currency currency)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(amount);
        ArgumentNullException.ThrowIfNull(currency);

        var lines = new List<ChangeLine>();
        var remaining = amount;
        var denominations = currency.Denominations;
        for (var i = 0; i < denominations.Count; i++)
        {
            var denomination = denominations[i];
            var maxCount = remaining / denomination.ValueInMinorUnits;
            var isSmallest = i == denominations.Count - 1;
            var count = isSmallest ? maxCount : _random.NextInt64(0, maxCount + 1);
            if (count > 0)
            {
                lines.Add(new ChangeLine(denomination, count));
                remaining -= count * denomination.ValueInMinorUnits;
            }
        }

        return lines;
    }
}
EOF
