using CashRegister.Domain.Change;

namespace CashRegister.Domain.Rules;

/// <summary>Applies when the amount owed, in minor units, is divisible by a configured divisor.</summary>
public sealed class OwedDivisibleByRule : IChangeRule
{
    private readonly int _divisor;

    public OwedDivisibleByRule(int divisor, string strategyKey)
    {
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(divisor);
        ArgumentException.ThrowIfNullOrWhiteSpace(strategyKey);
        _divisor = divisor;
        StrategyKey = strategyKey;
    }

    public string StrategyKey { get; }

    public bool AppliesTo(Transaction transaction)
    {
        ArgumentNullException.ThrowIfNull(transaction);
        return transaction.Owed % _divisor == 0;
    }
}
