using CashRegister.Domain.Currencies;

namespace CashRegister.Domain.Change;

/// <summary>
/// Fewest pieces, using the greedy algorithm. Greedy gives the optimal result for canonical
/// coin systems such as USD and EUR; a non-canonical currency would need its own strategy.
/// </summary>
public sealed class MinimalChangeStrategy : IChangeStrategy
{
    public string Key => ChangeStrategyKeys.Minimal;

    public IReadOnlyList<ChangeLine> MakeChange(long amount, Currency currency)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(amount);
        ArgumentNullException.ThrowIfNull(currency);

        var lines = new List<ChangeLine>();
        var remaining = amount;
        foreach (var denomination in currency.Denominations)
        {
            var count = remaining / denomination.ValueInMinorUnits;
            if (count > 0)
            {
                lines.Add(new ChangeLine(denomination, count));
                remaining -= count * denomination.ValueInMinorUnits;
            }
        }

        return lines;
    }
}

