using CashRegister.Domain.Currencies;

namespace CashRegister.Domain.Change;

/// <summary>
/// Takes a random count of each denomination, largest first. The smallest unit makes up
/// whatever is left, so the total is always exact.
/// </summary>
public sealed class RandomChangeStrategy : IChangeStrategy
{
    private readonly Random _random;

    public RandomChangeStrategy(Random random)
    {
        ArgumentNullException.ThrowIfNull(random);
        _random = random;
    }

    public string Key => ChangeStrategyKeys.Random;

    public IReadOnlyList<ChangeLine> MakeChange(long amount, Currency currency)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(amount);
        ArgumentNullException.ThrowIfNull(currency);

        var lines = new List<ChangeLine>();
        var remaining = amount;
        var denominations = currency.Denominations;
        for (var i = 0; i < denominations.Count; i++)
        {
            var denomination = denominations[i];
            var maxCount = remaining / denomination.ValueInMinorUnits;
            var isSmallest = i == denominations.Count - 1;
            var count = isSmallest ? maxCount : _random.NextInt64(0, maxCount + 1);
            if (count > 0)
            {
                lines.Add(new ChangeLine(denomination, count));
                remaining -= count * denomination.ValueInMinorUnits;
            }
        }

        return lines;
    }
}

