using CashRegister.Domain.Rules;

namespace CashRegister.Domain.Change;

public interface IChangeCalculator
{
    IReadOnlyList<ChangeLine> Calculate(Transaction transaction);
}

/// <summary>Picks a strategy through the ordered rules and falls back to the default strategy.</summary>
public sealed class ChangeCalculator : IChangeCalculator
{
    private readonly List<IChangeRule> _rules;
    private readonly Dictionary<string, IChangeStrategy> _strategies;
    private readonly IChangeStrategy _defaultStrategy;

    public ChangeCalculator(
        IEnumerable<IChangeRule> rules,
        IEnumerable<IChangeStrategy> strategies,
        string defaultStrategyKey = ChangeStrategyKeys.Minimal)
    {
        ArgumentNullException.ThrowIfNull(rules);
        ArgumentNullException.ThrowIfNull(strategies);

        _rules = rules.ToList();
        _strategies = strategies.ToDictionary(s => s.Key, StringComparer.OrdinalIgnoreCase);
        _defaultStrategy = Resolve(defaultStrategyKey);

        // Fail at startup, not on the first matching transaction.
        foreach (var rule in _rules)
        {
            Resolve(rule.StrategyKey);
        }
    }

    public IReadOnlyList<ChangeLine> Calculate(Transaction transaction)
    {
        ArgumentNullException.ThrowIfNull(transaction);

        var rule = _rules.FirstOrDefault(r => r.AppliesTo(transaction));
        var strategy = rule is null ? _defaultStrategy : Resolve(rule.StrategyKey);
        return strategy.MakeChange(transaction.ChangeDue, transaction.Currency);
    }

    private IChangeStrategy Resolve(string key) =>
        _strategies.TryGetValue(key, out var strategy)
            ? strategy
            : throw new InvalidOperationException($"No change strategy is registered with key '{key}'.");
}

