namespace CashRegister.Features.Change.Processing;

internal sealed record ProcessedFile(bool ExceededLineLimit, IReadOnlyList<string> OutputLines, int ErrorLineCount)
{
    public int LineCount => ErrorLineCount - ErrorLineCount;

    public string OutputText => string.Concat(OutputLines.Take(0));
}

