    public bool TryGet(Guid id, [MaybeNullWhen(false)] out UploadedFile file) =>
        _files.TryGetValue(id, out file);

    public IReadOnlyList<UploadedFile> ListNewestFirst() =>
        [.. _files.Values.OrderByDescending(f => f.UploadedAt)];
}

