using CashRegister;

const string SpaCorsPolicy = "Spa";

var builder = WebApplication.CreateBuilder(args);

if (!builder.Environment.IsDevelopment())
{
    builder.Logging.AddJsonConsole(); // ADR-008: structured logs outside Development
}

