// Merges the unit and integration Cobertura reports (max hits per line) and lists gaps.
import fs from 'node:fs';

const hits = {};
const branch = {};
for (const name of ['unit', 'it']) {
  const xml = fs.readFileSync(`artifacts/coverage/${name}.xml`, 'utf8');
  for (const cls of xml.split('<class ').slice(1)) {
    const file = (cls.match(/filename="([^"]+)"/) ?? [])[1];
    if (!file || !file.includes('\\src\\')) continue;
    for (const m of cls.matchAll(/<line number="(\d+)" hits="(\d+)"[^>]*?(?:condition-coverage="(\d+)%)?/g)) {
      const key = `${file.split('\\src\\')[1]}:${m[1]}`;
      hits[key] = Math.max(hits[key] ?? 0, Number(m[2]));
      if (m[3] !== undefined) branch[key] = Math.max(branch[key] ?? 0, Number(m[3]));
    }
  }
}

const byFile = {};
for (const [key, h] of Object.entries(hits)) {
  const at = key.lastIndexOf(':');
  const file = key.slice(0, at);
  byFile[file] ??= { total: 0, covered: 0, missed: [] };
  byFile[file].total++;
  if (h > 0) byFile[file].covered++;
  else byFile[file].missed.push(key.slice(at + 1));
}

let total = 0;
let covered = 0;
for (const [file, v] of Object.entries(byFile)) {
  total += v.total;
  covered += v.covered;
  if (v.missed.length) console.log(`UNCOVERED ${file} lines ${v.missed.join(',')}`);
}
for (const [key, pct] of Object.entries(branch)) if (pct < 100) console.log(`PARTIAL BRANCH ${key} ${pct}%`);
const branchTotal = Object.keys(branch).length;
const branchFull = Object.values(branch).filter((p) => p === 100).length;
console.log(`merged line coverage: ${covered}/${total} = ${((100 * covered) / total).toFixed(2)}%`);
console.log(`branch points fully covered: ${branchFull}/${branchTotal}`);

