// Renders Claude Code session logs (JSONL) as readable Markdown, in order, without dropping entries.
// Usage: node jsonl-to-md.mjs <out.md> <session1.jsonl> [session2.jsonl ...]
import fs from 'node:fs';
import path from 'node:path';

const [out, ...inputs] = process.argv.slice(2);
const fence = (text) => {
  const body = String(text ?? '');
  const ticks = body.includes('```') ? '````' : '```';
  return `${ticks}\n${body}\n${ticks}`;
};

const parts = [];
const stats = {};
for (const file of inputs) {
  const entries = fs
    .readFileSync(file, 'utf8')
    .split('\n')
    .filter(Boolean)
    .map((line) => {
      try {
        return JSON.parse(line);
      } catch {
        return { type: 'unparseable', raw: line };
      }
    });
  parts.push(`\n# Session ${path.basename(file, '.jsonl')}\n\n${entries.length} log entries.\n`);

  for (const e of entries) {
    stats[e.type] = (stats[e.type] ?? 0) + 1;
    const when = e.timestamp ? ` · ${e.timestamp}` : '';
    if (e.type === 'user' || e.type === 'assistant') {
      const content = e.message?.content;
      const blocks = typeof content === 'string' ? [{ type: 'text', text: content }] : (content ?? []);
      for (const b of blocks) {
        if (b.type === 'text') parts.push(`\n## ${e.type === 'user' ? 'User' : 'Assistant'}${when}\n\n${b.text}\n`);
        else if (b.type === 'thinking') parts.push(`\n### Assistant (reasoning)${when}\n\n${fence(b.thinking)}\n`);
        else if (b.type === 'redacted_thinking') parts.push(`\n### Assistant (reasoning, redacted by the platform)${when}\n`);
        else if (b.type === 'tool_use') parts.push(`\n### Tool call: ${b.name}${when}\n\n${fence(JSON.stringify(b.input, null, 2))}\n`);
        else if (b.type === 'tool_result') {
          const text = Array.isArray(b.content)
            ? b.content.map((c) => (c.type === 'text' ? c.text : `[${c.type}]`)).join('\n')
            : b.content;
          parts.push(`\n### Tool result${b.is_error ? ' (error)' : ''}${when}\n\n${fence(text)}\n`);
        } else parts.push(`\n### ${e.type} block: ${b.type}${when}\n\n${fence(JSON.stringify(b, null, 2))}\n`);
      }
    } else if (e.type === 'summary') {
      parts.push(`\n## Context summary${when}\n\n${e.summary}\n`);
    } else {
      parts.push(`\n### Log entry: ${e.type}${when}\n\n${fence(JSON.stringify(e))}\n`);
    }
  }
}

fs.writeFileSync(out, `# Full AI session transcript\n\nRendered from the raw Claude Code session logs, every entry in order.\n${parts.join('')}`);
console.log(JSON.stringify(stats));

