// Renders Claude Code session logs (JSONL) as readable Markdown, in order, without dropping entries.
// Usage: node jsonl-to-md.mjs <out.md> <session1.jsonl> [session2.jsonl ...]
import fs from 'node:fs';
import path from 'node:path';

const [out, ...inputs] = process.argv.slice(2);
const fence = (text) => {
  const body = String(text ?? '');
  const ticks = body.includes('```') ? '````' : '```';
  return `${ticks}\n${body}\n${ticks}`;
};

const parts = [];
const stats = {};
for (const file of inputs) {
  const entries = fs
    .readFileSync(file, 'utf8')
    .split('\n')
    .filter(Boolean)
    .map((line) => {
      try {
        return JSON.parse(line);
      } catch {
        return { type: 'unparseable', raw: line };
      }
    });
  parts.push(`\n# Session ${path.basename(file, '.jsonl')}\n\n${entries.length} log entries.\n`);

  for (const e of entries) {
    stats[e.type] = (stats[e.type] ?? 0) + 1;
    const when = e.timestamp ? ` · ${e.timestamp}` : '';
    if (e.type === 'user' || e.type === 'assistant') {
      const content = e.message?.content;
      const blocks = typeof content === 'string' ? [{ type: 'text', text: content }] : (content ?? []);
      for (const b of blocks) {
        if (b.type === 'text') parts.push(`\n## ${e.type === 'user' ? 'User' : 'Assistant'}${when}\n\n${b.text}\n`);
        else if (b.type === 'thinking') parts.push(`\n### Assistant (reasoning)${when}\n\n${fence(b.thinking)}\n`);
